  "root_cause": {
    "category": "other",
    "service": "queue-master",
    "summary": "The Docker socket (/var/run/docker.sock) is missing, preventing queue-master from launching worker containers and likely causing downstream capacity loss."
  },
  "confidence": "medium",
  "causal_chain": [
    {
      "claim": "The Docker socket (/var/run/docker.sock) is missing, causing connection failures from queue-master to the Docker daemon.",
      "status": "confirmed",
      "cites": ["queue-master-L00003", "queue-master-L00009", "queue-master-L00012", "queue-master-L0001b"]
    },
    {
      "claim": "Queue-master repeatedly fails to launch or remove worker containers due to the Docker socket errors.",
      "status": "confirmed",
      "cites": ["queue-master-L00009", "queue-master-L00012", "queue-master-L0001b", "queue-master-L00024"]
    },
    {
      "claim": "The inability to spawn workers reduces capacity for asynchronous order processing, potentially causing order fulfillment failures.",
      "status": "uncertain",
      "cites": ["queue-master-L00009", "queue-master-L00012"]
    },
    {
      "claim": "The front-end (gateway) returns HTTP 406 responses with \"Payment declined: amount exceeds 100.00\" to users.",
      "status": "confirmed",
      "cites": ["front-end-L0000c", "front-end-L0000d", "front-end-L00071", "front-end-L00072"]
    }
  ],
  "alternatives": [
    {
      "category": "config_regression",
      "service": "orders",
      "why_less_likely": "The front-end logs show a consistent business-rule error (amount exceeds 100.00) which could stem from a configuration change lowering the payment limit, but no deploy or config change events are present in the telemetry.",
      "cites": ["front-end-L0000c"]
    },
    {
      "category": "process_crash",
      "service": "payments",
      "why_less_likely": "If the payment service had crashed, the orders service would likely surface connection errors rather than a specific \"amount exceeds\" business exception; also no payment service logs are available to confirm a crash.",
